  ctx.fillStyle = '#273b3745'; ctx.beginPath(); ctx.ellipse(2, 5, 28, 16, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#222a28';
  for (const x of [-12, 12]) { ctx.fillRect(x - 5, -12, 10, 4); ctx.fillRect(x - 5, 8, 10, 4); }
