  ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
  ctx.fillStyle = '#26382f45'; ctx.beginPath(); ctx.ellipse(2, 6, isPlayer ? 13 : 12, 8, 0, 0, TAU); ctx.fill();
