280:   function update(dt) {
281:     if (!started || paused || ended) return;
282:     elapsed += dt; fpsElapsed += dt; fpsFrames++;
283:     if (fpsElapsed >= .5) { ui.fps.textContent = Math.round(fpsFrames / fpsElapsed); fpsElapsed = 0; fpsFrames = 0; }
284:     if (player.invuln > 0) player.invuln -= dt;
285:     if (damageFlash > 0) damageFlash = Math.max(0, damageFlash - dt * 1.8);
286:     if (toastTimer > 0 && (toastTimer -= dt) <= 0) ui.toast.classList.remove('show');
287:     if (fireTimer > 0) fireTimer -= dt;
288:     if (reloadTimer > 0 && (reloadTimer -= dt) <= 0) finishReload();
289:     updatePlayer(dt); updateEnemies(dt); updateBullets(dt); updateParticles(dt); updateCamera(dt); updateInteraction(); updateHud();
290:   }
291:   function updatePlayer(dt) {
292:     let ix = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0) + stick.x;
293:     let iy = (keys.has('s') || keys.has('arrowdown') ? 1 : 0) - (keys.has('w') || keys.has('arrowup') ? 1 : 0) + stick.y;
294:     const mag = Math.hypot(ix, iy); if (mag > 1) { ix /= mag; iy /= mag; }
295:     const running = sprint || keys.has('shift');
296:     if (currentVehicle) {
297:       const throttle = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0) - stick.y;
298:       const steer = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0) + stick.x;
299:       currentVehicle.speed += throttle * 290 * dt; currentVehicle.speed *= Math.pow(.982, dt * 60); currentVehicle.speed = clamp(currentVehicle.speed, -120, 330);
300:       currentVehicle.angle += steer * (currentVehicle.speed / 330) * 2.45 * dt;
301:       const nx = player.x + Math.cos(currentVehicle.angle) * currentVehicle.speed * dt, ny = player.y + Math.sin(currentVehicle.angle) * currentVehicle.speed * dt;
302:       if (!blocked(nx, ny, 22)) { player.x = nx; player.y = ny; currentVehicle.x = nx; currentVehicle.y = ny; }
303:       if (Math.abs(currentVehicle.speed) > 40) player.angle = currentVehicle.angle;
304:     } else {
305:       const max = player.speed * (running ? 1.46 : 1);
306:       player.vx += ((ix * max) - player.vx) * Math.min(1, dt * 10);
307:       player.vy += ((iy * max) - player.vy) * Math.min(1, dt * 10);
308:       const nx = player.x + player.vx * dt, ny = player.y + player.vy * dt;
309:       if (!blocked(nx, player.y, player.radius)) player.x = nx; else player.vx = 0;
310:       if (!blocked(player.x, ny, player.radius)) player.y = ny; else player.vy = 0;
311:       if (pointer.active && !isTouchDevice()) aimAngle = Math.atan2(pointer.y + camera.y - player.y, pointer.x + camera.x - player.x);
312:       if (aimTouchAngle !== null) aimAngle = aimTouchAngle;
313:       if (Math.hypot(ix, iy) > .05 && !pointer.active && aimTouchAngle === null) aimAngle = Math.atan2(iy, ix);
314:       player.angle = aimAngle;
315:     }
316:     if (firing || pointer.down) attemptFire();
317:     // Nearby collisions and opportunistic vehicle takedowns.
318:     for (const e of enemies) if (!e.dead && currentVehicle && Math.abs(currentVehicle.speed) > 140 && dist2(player, e) < 34 ** 2) damageEnemy(e, 100, true);
319:   }
320:   function updateEnemies(dt) {
321:     for (const e of enemies) {
322:       if (e.dead) continue;
323:       e.hit = Math.max(0, e.hit - dt); e.fire -= dt;
324:       const d = Math.sqrt(dist2(player, e));
325:       if (d < 430) e.state = 'alert';
326:       if (d < 390) {
327:         const desired = Math.atan2(player.y - e.y, player.x - e.x); e.angle = desired;
328:         if (d > 180) {
329:           const strafe = Math.sin(elapsed * 1.8 + e.seed) * 25;
330:           const vx = Math.cos(desired) * 48 + Math.cos(desired + Math.PI / 2) * strafe * e.strafe;
331:           const vy = Math.sin(desired) * 48 + Math.sin(desired + Math.PI / 2) * strafe * e.strafe;
332:           const nx = e.x + vx * dt, ny = e.y + vy * dt;
333:           if (!blocked(nx, e.y, 13)) e.x = nx;
334:           if (!blocked(e.x, ny, 13)) e.y = ny;
335:         }
336:         if (e.fire <= 0 && d < 380) { e.fire = rand(.75, 1.5); bullets.push({ x: e.x + Math.cos(desired) * 22, y: e.y + Math.sin(desired) * 22, vx: Math.cos(desired) * 285, vy: Math.sin(desired) * 285, life: 1.5, friendly: false, damage: rand(7, 11) }); }
337:       }
338:     }
339:   }
340:   function updateBullets(dt) {
341:     for (let i = bullets.length - 1; i >= 0; i--) {
342:       const b = bullets[i]; b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
343:       let remove = b.life <= 0 || blocked(b.x, b.y, 2);
344:       if (b.friendly) {
345:         for (const e of enemies) if (!e.dead && dist2(b, e) < 22 ** 2) { damageEnemy(e, b.damage, true); remove = true; break; }
346:       } else if (!currentVehicle && player.invuln <= 0 && dist2(b, player) < 18 ** 2) { damagePlayer(b.damage); remove = true; }
347:       else if (currentVehicle && dist2(b, player) < 23 ** 2) { damagePlayer(b.damage * .55); remove = true; }
348:       if (remove) bullets.splice(i, 1);
349:     }
350:   }
351:   function updateParticles(dt) {
352:     for (let i = particles.length - 1; i >= 0; i--) { particles[i].life -= dt; particles[i].x += particles[i].vx * dt; particles[i].y += particles[i].vy * dt; particles[i].vx *= .97; particles[i].vy *= .97; if (particles[i].life <= 0) particles.splice(i, 1); }
353:   }
354:   function updateCamera(dt) {
